update post_comment
   set content = #{content},
       updated_at = systimestamp
 where post_comment_seq = #{postCommentSeq}
   and post_seq = #{postSeq}
   and member_seq = #{memberSeq}
   and is_deleted = 'N'

update post_comment
   set is_deleted = 'Y',
       updated_at = systimestamp
 where post_comment_seq = #{postCommentSeq}
   and post_seq = #{postSeq}
   and member_seq = #{memberSeq}
   and is_deleted = 'N'
